export interface SocialLink {
    id: string;
    platform: 'facebook' | 'instagram' | 'youtube' | 'twitter' | 'linkedin';
    url: string;
    isActive?: boolean;
}

export interface QuickLink {
    id: string;
    label: string;
    href: string;
    isActive?: boolean;
    order?: number;
}

export interface AddressConfig {
    icon: string;
    isoLogo: string;
    text?: string;
}

export interface ContactConfig {
    icon: string;
    phone: string;
    phoneLink: string;
    email: string;
    emailLink: string;
    socialLinks: SocialLink[];
}

export interface QuickAccessConfig {
    icon: string;
    links: QuickLink[];
}

export interface FooterConfig {
    address: AddressConfig;
    contact: ContactConfig;
    quickAccess: QuickAccessConfig;
    copyrightLogo: string;
    copyrightText?: string;
}

// API Response Types
export interface FooterApiResponse {
    data: {
        id: number;
        attributes: {
            address: AddressConfig;
            contact: ContactConfig;
            quickAccess: QuickAccessConfig;
            copyrightLogo: {
                data: {
                    attributes: {
                        url: string;
                    };
                };
            };
            copyrightText?: string;
            locale: string;
            publishedAt: string;
        };
    };
    meta?: {
        pagination?: {
            page: number;
            pageSize: number;
            pageCount: number;
            total: number;
        };
    };
}


